// The elements ren-json gives a role by themselves, each in the contexts
// that change it, as views: test/fixtures/roles.json holds the role Chrome's
// accessibility tree gives each one ren-dom renders (ren-html's
// scripts/roles-oracle.mjs records it), and test/roles.test.jsx checks
// ren-json's against it. The element probed is the one named "probe" (a
// name changes no role; ren-json keeps it as the node's `name`); a table
// header's text is "Probe", its key in a table's records.

import { Action, Edit, Image, View } from 'ren-core';

const P = 'probe';
/** The header, footer and aside probed in each context. */
const PROBES = /** @type {Record<string, () => any>} */ ({
  aside: () => <aside name={P}>Text</aside>,
  footer: () => <footer name={P}>Text</footer>,
  header: () => <header name={P}>Text</header>,
});
/** A header, footer or aside in `wrap`. @param {string} tag @param {(child: any) => any} wrap */
const inside = (tag, wrap) => () => wrap(PROBES[tag]());
const contexts = /** @type {[string, (child: any) => any][]} */ ([
  ['at the top', c => <div>{c}</div>],
  ['in main', c => <main>{c}</main>],
  ['in an article', c => <article>{c}</article>],
  ['in an unnamed section', c => <section>{c}</section>],
  ['in a named section', c => <section aria-label="Part">{c}</section>],
  ['in an aside', c => <aside>{c}</aside>],
  ['in a nav', c => <nav>{c}</nav>],
  ['in a div with role region', c => <div role="region" aria-label="Part">{c}</div>],
  ['in a div with role article', c => <div role="article">{c}</div>],
  ['in a div with role main', c => <div role="main">{c}</div>],
  ['in a div with role navigation', c => <div role="navigation">{c}</div>],
  ['in a div with role complementary', c => <div role="complementary">{c}</div>],
]);
/** A table of a header row and one body row, `row` its body row's cells. @param {any} head @param {any} row */
const table = (head, row) => () => <table>{head === null ? null : <thead>{head}</thead>}<tbody>{row}</tbody></table>;

/** @type {[string, () => any][]} */
export const views = [
  ['Action', () => <Action name={P} text="Go" />],
  ['Edit', () => <Edit name={P} label="Name" />],
  ['Image', () => <Image name={P} source="a.png" label="A lamp" />],
  ['a with href', () => <a name={P} href="/x">x</a>],
  ['a without href', () => <p><a name={P}>x</a> y</p>],
  ['article', () => <article name={P}>x</article>],
  ...contexts.map(([where, wrap]) => /** @type {[string, () => any]} */ ([`aside ${where}`, inside('aside', wrap)])),
  ['a named aside in a section', () => <section aria-label="Part"><aside name={P} aria-label="Side">x</aside></section>],
  ['blockquote', () => <blockquote name={P}>x</blockquote>],
  ['button', () => <button name={P}>x</button>],
  ['caption', () => <table><caption name={P}>Cap</caption><tbody><tr><td>x</td></tr></tbody></table>],
  ['code', () => <p>Run <code name={P}>npm test</code> now</p>],
  ['dd', () => <dl><dt>T</dt><dd name={P}>D</dd></dl>],
  ['details', () => <details name={P} open><summary>S</summary>x</details>],
  ['dialog', () => <dialog name={P} open>x</dialog>],
  ['dl', () => <dl name={P}><dt>T</dt><dd>D</dd></dl>],
  ['dt', () => <dl><dt name={P}>T</dt><dd>D</dd></dl>],
  ['fieldset', () => <fieldset name={P}><legend>L</legend>x</fieldset>],
  ['figcaption', () => <figure><figcaption name={P}>C</figcaption>x</figure>],
  ['figure', () => <figure name={P}><figcaption>C</figcaption>x</figure>],
  ...contexts.map(([where, wrap]) => /** @type {[string, () => any]} */ ([`footer ${where}`, inside('footer', wrap)])),
  ['form without a name', () => <form name={P}><input aria-label="q" /></form>],
  ['form with a name', () => <form name={P} aria-label="Search"><input aria-label="q" /></form>],
  ['h1', () => <h1 name={P}>x</h1>],
  ['h4', () => <h4 name={P}>x</h4>],
  ...contexts.map(([where, wrap]) => /** @type {[string, () => any]} */ ([`header ${where}`, inside('header', wrap)])),
  ['img with alt', () => <img name={P} alt="A lamp" src="a.png" />],
  ['img with an empty alt', () => <img name={P} alt="" src="a.png" />],
  ['img with an empty alt and a label', () => <img name={P} alt="" aria-label="A lamp" src="a.png" />],
  ['img with an empty alt and a title', () => <img name={P} alt="" title="A lamp" src="a.png" />],
  ['img without alt', () => <img name={P} src="a.png" />],
  ['li in a ul', () => <ul><li name={P}>x</li></ul>],
  ['main', () => <main name={P}>x</main>],
  ['menu', () => <menu name={P}><li>x</li></menu>],
  ['meter', () => <meter name={P} value={0.5}>half</meter>],
  ['nav', () => <nav name={P}>x</nav>],
  ['ol', () => <ol name={P}><li>x</li></ol>],
  ['option in a select', () => <select aria-label="s"><option name={P}>x</option></select>],
  ['optgroup', () => <select aria-label="s"><optgroup name={P} label="G"><option>x</option></optgroup></select>],
  ['output', () => <output name={P}>3</output>],
  ['p', () => <p name={P}>x</p>],
  ['pre', () => <pre name={P}>x = 1</pre>],
  ['progress', () => <progress name={P} value={0.5}>half</progress>],
  ['search', () => <search name={P}>x</search>],
  ['section without a name', () => <section name={P}>x</section>],
  ['section with a name', () => <section name={P} aria-label="Part">x</section>],
  ['select', () => <select name={P} aria-label="s"><option>a</option></select>],
  ['select multiple', () => <select name={P} multiple aria-label="s"><option>a</option></select>],
  ['select size 1', () => <select name={P} size={1} aria-label="s"><option>a</option></select>],
  ['select size 4', () => <select name={P} size={4} aria-label="s"><option>a</option></select>],
  ['summary', () => <details><summary name={P}>S</summary>x</details>],
  ['table', () => <table name={P}><caption>Cap</caption><tbody><tr><td>x</td><td>y</td></tr></tbody></table>],
  ['td in a table', () => <table><caption>Cap</caption><tbody><tr><td name={P}>x</td><td>y</td></tr></tbody></table>],
  ['td in a grid', () => <table role="grid"><tbody><tr><td name={P}>x</td></tr></tbody></table>],
  ['td in a treegrid', () => <table role="treegrid"><tbody><tr><td name={P}>x</td></tr></tbody></table>],
  ['textarea', () => <textarea name={P} aria-label="t" />],
  ['th in a thead', table(<tr><th>Probe</th><th>Age</th></tr>, <tr><td>Ada</td><td>36</td></tr>)],
  ['th starting a body row', table(<tr><th /><th>Q1</th></tr>, [<tr><th>Probe</th><td>10</td></tr>, <tr><th>Cost</th><td>4</td></tr>])],
  ['th starting a body row, no thead', table(null, [<tr><th>Probe</th><td>10</td></tr>, <tr><th>Cost</th><td>4</td></tr>])],
  ['th ending a body row', table(null, [<tr><td>10</td><th>Probe</th></tr>, <tr><td>4</td><th>Cost</th></tr>])],
  ['th before an empty td', table(null, [<tr><th>Probe</th><td /></tr>, <tr><th>Cost</th><td /></tr>])],
  ['th before an empty td, then a td', table(null, [<tr><th>Probe</th><td /><td>1</td></tr>, <tr><th>Cost</th><td /><td>2</td></tr>])],
  ['th between ths in a body row', table(null, [<tr><th>A</th><th>Probe</th><th>B</th></tr>, <tr><td>1</td><td>2</td><td>3</td></tr>])],
  ['th alone in its row', table(null, [<tr><th>Probe</th></tr>, <tr><td>1</td></tr>])],
  ['th, the first of a row of ths', table(null, [<tr><th>Probe</th><th>B</th></tr>, <tr><td>1</td><td>2</td></tr>])],
  ['th with scope row in a thead', table(<tr><th scope="row">Probe</th><th>B</th></tr>, <tr><td>1</td><td>2</td></tr>)],
  ['th with scope col starting a body row', table(null, [<tr><th scope="col">Probe</th><td>1</td></tr>, <tr><th scope="col">Cost</th><td>2</td></tr>])],
  ['th with scope rowgroup', table(null, [<tr><th scope="rowgroup">Probe</th><td>1</td></tr>, <tr><th scope="rowgroup">Cost</th><td>2</td></tr>])],
  ['th with scope colgroup', table(null, [<tr><th scope="colgroup">Probe</th><th>B</th></tr>, <tr><td>1</td><td>2</td></tr>])],
  ['time', () => <p><time name={P} datetime="2026-09-30">today</time></p>],
  ['tr', () => <table><caption>Cap</caption><tbody><tr name={P}><td>x</td><td>y</td></tr></tbody></table>],
  ['ul', () => <ul name={P}><li>x</li></ul>],
  ...['text', 'email', 'tel', 'url', 'password', 'search', 'number', 'range', 'checkbox', 'radio', 'button', 'submit', 'reset', 'image', 'file', 'color', 'date', 'time', 'datetime-local', 'month', 'week'].map(
    type => /** @type {[string, () => any]} */ ([`input type ${type}`, () => <input name={P} type={type} aria-label="f" alt="f" />]),
  ),
  ['input without a type', () => <input name={P} aria-label="f" />],
  ['input with a list', () => <div><input name={P} list="d" aria-label="f" /><datalist id="d"><option value="x" /></datalist></div>],
  ['input with a list no datalist has', () => <input name={P} list="none" aria-label="f" />],
  ['input type search with a list', () => <div><input name={P} type="search" list="d" aria-label="f" /><datalist id="d"><option value="x" /></datalist></div>],
  ['input type email with a list', () => <div><input name={P} type="email" list="d" aria-label="f" /><datalist id="d"><option value="x" /></datalist></div>],
  ['input type number with a list', () => <div><input name={P} type="number" list="d" aria-label="f" /><datalist id="d"><option value="1" /></datalist></div>],
  // An id, and a prop naming one, given as a number or a boolean: the text ren-dom writes (id and list 71 are "71").
  ['input with a list given as a number', () => <div><input name={P} list={71} aria-label="f" /><datalist id={71}><option value="x" /></datalist></div>],
  // A section's or an aside's name as Chrome counts it: a title, or an aria-labelledby naming an element, even an empty one.
  ['section with a title', () => <section name={P} title="Part">x</section>],
  ['section labelledby an empty element', () => <div><span id="empty-s" /><section name={P} aria-labelledby="empty-s">x</section></div>],
  ['section labelledby no element', () => <section name={P} aria-labelledby="none-s">x</section>],
  ['section labelledby an element, given as a number', () => <div><span id={72} /><section name={P} aria-labelledby={72}>x</section></div>],
  ['section labelledby an element, given as false', () => <div><span id={false} /><section name={P} aria-labelledby={false}>x</section></div>],
  ['section with a blank aria-label', () => <section name={P} aria-label=" ">x</section>],
  ['aside in a section, with a title', () => <section><aside name={P} title="Side">x</aside></section>],
  ['aside in a section, labelledby an empty element', () => <section><span id="empty-a" /><aside name={P} aria-labelledby="empty-a">x</aside></section>],
  // A region or form role token counts only on a named element.
  ['div with role region, no name', () => <div name={P} role="region">x</div>],
  ['div with role region and a title', () => <div name={P} role="region" title="Part">x</div>],
  ['div with role region article', () => <div name={P} role="region article">x</div>],
  ['div with role region article, named', () => <div name={P} role="region article" aria-label="Part">x</div>],
  ['div with role form, no name', () => <div name={P} role="form">x</div>],
  ['div with role form search', () => <div name={P} role="form search">x</div>],
  ['header in a div with role region article', () => <div role="region article"><header name={P}>T</header></div>],
  // A sectioning ancestor counts by the role it has, not its tag.
  ['header in a section with role none', () => <section role="none"><header name={P}>T</header></section>],
  ['header in an article with role presentation', () => <article role="presentation"><header name={P}>T</header></article>],
  ['header in main with role none', () => <main role="none"><header name={P}>T</header></main>],
  ['header in a nav with role none', () => <nav role="none"><header name={P}>T</header></nav>],
  ['header in an aside with role note', () => <aside role="note"><header name={P}>T</header></aside>],
  ['footer in a section with role none', () => <section role="none"><footer name={P}>T</footer></section>],
  ['aside in a section with role none', () => <section role="none"><aside name={P}>x</aside></section>],
  ['header in a section with role region, no name', () => <section role="region"><header name={P}>T</header></section>],
  ['header in a section with role none, in a div with role article', () => <div role="article"><section role="none"><header name={P}>T</header></section></div>],
  // A table with no caption, header, summary or role: Chrome's layout table.
  ['table without a caption or headers', () => <table name={P}><tbody><tr><td>x</td><td>y</td></tr></tbody></table>],
  ['td in a table without a caption or headers', () => <table><tbody><tr><td name={P}>x</td><td>y</td></tr></tbody></table>],
  // What the page does not show: Chrome's tree ignores it, and the data drops it.
  ['dialog closed', () => <dialog name={P}>x</dialog>],
  ['button in a closed dialog', () => <div><dialog><button name={P}>x</button></dialog></div>],
  ['button in an open dialog', () => <div><dialog open><button name={P}>x</button></dialog></div>],
  ['button with a style object of display none', () => <div><button name={P} style={{ display: 'none' }}>x</button></div>],
  ['button in a div with a style text of display none', () => <div style="color: red; display: NONE">y<button name={P}>x</button></div>],
  ['button in a div whose display none a later display overrides', () => <div style="display: none; display: block">y<button name={P}>x</button></div>],
  ['button in a div whose display none is important', () => <div style="display: none !important; display: block">y<button name={P}>x</button></div>],
  ['button in a div whose display none an invalid one does not override', () => <div style="display: none; display: banana">y<button name={P}>x</button></div>],
  ['button in a div with display none in a string', () => <div style={'font-family: "a;display:none"'}>y<button name={P}>x</button></div>],
  ['button in a closed details', () => <details><summary>S</summary><button name={P}>x</button></details>],
  ['button in an open details', () => <details open><summary>S</summary><button name={P}>x</button></details>],
  ['second summary in a closed details', () => <details><summary>S</summary><summary name={P}>T</summary></details>],
  ['option in a datalist', () => <div><input list="dl" aria-label="f" /><datalist id="dl"><option name={P} value="x">X</option></datalist></div>],
  ['button in a video', () => <video controls><button name={P}>x</button></video>],
  ['button in an audio', () => <audio controls><button name={P}>x</button></audio>],
  ['button in a select', () => <select aria-label="s"><option>a</option><button name={P}>x</button></select>],
  ['button in a div in a select', () => <select aria-label="s"><div><option>a</option><button name={P}>x</button></div></select>],
  ['button in an optgroup', () => <select aria-label="s"><optgroup label="G"><option>a</option><button name={P}>x</button></optgroup></select>],
  ['option in a span in a select', () => <select aria-label="s"><option>a</option><span><option name={P}>b</option></span></select>],
  ['option in a div in a select', () => <select aria-label="s"><option>a</option><div><option name={P}>b</option></div></select>],
  // An inert region: out of the tree, as the page takes no input there.
  ['button in an inert View', () => <View inert><button name={P}>x</button></View>],
  ['button in a View not inert', () => <View inert={false}><button name={P}>x</button></View>],
  ['button in an inert div', () => <div inert><button name={P}>x</button></div>],
  ['button in a div not inert', () => <div inert={false}><button name={P}>x</button></div>],
];
